const item = $input.first();
const body = (item.json && item.json.body) || {};
const text = (body.text || '').toString().trim();
if (!text) throw new Error('Missing body.text: nothing to classify');
if (text.length > 4000) throw new Error('text too long (>4000 chars)');
const vault_path = (body.vault_path || './obsidian-vault').toString();
const id = require('crypto').createHash('sha1').update(text).digest('hex').slice(0, 12);
return [{ json: { note_id: id, text, vault_path, received_at: new Date().toISOString() } }];

const resp = $json;
const raw = resp && resp.content && resp.content[0] && resp.content[0].text;
if (!raw) throw new Error('Anthropic response missing content[0].text');
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { throw new Error('Model did not return valid JSON: ' + raw.slice(0, 200)); }
const valid = ['idea', 'todo', 'resource', 'project'];
if (!valid.includes(parsed.type)) throw new Error('Invalid classification type: ' + parsed.type);
if (typeof parsed.markdown !== 'string' || !parsed.markdown.trim()) throw new Error('Model returned empty markdown');
const prev = $('Validate Payload').first().json;
const safeType = parsed.type;
const fileName = prev.vault_path.replace(/\/+$/, '') + '/' + safeType + '/' + prev.note_id + '.md';
return [{ json: { note_id: prev.note_id, type: safeType, title: parsed.title || 'Untitled', tags: parsed.tags || [], fileName, markdown: parsed.markdown } }];

const sourceId="Da0EUZAu0ve";
const sourceUrl="https://www.instagram.com/_no_hype_ai/reel/Da0EUZAu0ve/";
const variant='USER_STACK';
const seen=new Set();
const hash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16).padStart(8,'0');};
return $input.all().map(({json:j},i)=>{
  const recordKey=String(j.row_id||j.clip_id||j.note_id||j.fileName||j.output_path||j.title||i);
  const idempotencyKey=hash(sourceId+'|'+recordKey);
  if(seen.has(idempotencyKey)) throw new Error('Duplicate output in one execution: '+idempotencyKey);
  seen.add(idempotencyKey);
  return {json:{...j,source_provenance:{source_id:sourceId,source_url:sourceUrl,variant},idempotency_key:idempotencyKey,review_status:'needs_human_review',review_notes:Array.isArray(j.review_notes)?j.review_notes:[],external_actions_enabled:false}};
});
